            root.querySelector('#opsListNote').textContent=`${rows.length} de ${group==='users'?d.userCount:d.branchCount} ${group==='users'?'responsables':'sucursales'} con actividad. Hasta 200, ordenados inicialmente por compras. Los totales superiores incluyen todos.`;
            root.querySelector('#opsPeople').innerHTML=rows.map(r=>`<article class="ops-person"><div><h4>${esc(r.name)}</h4>${group==='users'&&r.state!=='ACTIVE'?'<span class="tag">Historial · acceso retirado</span>':''}<progress max="${maximum}" value="${r.purchases}" aria-label="${r.purchases} compras"></progress><small>${r.buyers} clientes que compraron</small></div><dl><div><dt>Compras</dt><dd>${r.purchases}</dd></div><div><dt>Total pagado</dt><dd>${esc(money(r.paidMinor,c))}</dd></div><div><dt>Premios</dt><dd>${r.redemptions}</dd></div></dl>${r.id?`<button type="button" class="quiet" data-ops-history="${esc(r.id)}">Ver actividad</button>`:'<span class="small">Atribución histórica incompleta</span>'}</article>`).join('')||'<p>No hay actividad con estos filtros.</p>';
