        const weekdays=['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'],max=Math.max(1,...d.hours.map(h=>Number(h.purchases))),hours=new Map(d.hours.map(h=>[h.weekday+'-'+h.hour,h]));
